sys_script_include.script:
var ReadinessScorer = Class.create();

ReadinessScorer.prototype = {

    initialize: function() {},

    calculateScore: function(assessmentSysId) {

        gs.info('SCORER INPUT: ' + assessmentSysId);

        var threshold = 70;

        var assessmentGR = new GlideRecord('x_1858206_sentin_0_readiness_assessment');

        if (assessmentGR.get(assessmentSysId)) {

            gs.info('ASSESSMENT FOUND: ' + assessmentGR.getDisplayValue());

            var policyId = assessmentGR.getValue('policy');

            if (policyId) {

                var policyGR = new GlideRecord('x_1858206_sentin_0_readiness_policy');

                if (policyGR.get(policyId)) {

                    var policyThreshold = parseInt(
                        policyGR.getValue('pass_threshold'),
                        10
                    );

                    if (!isNaN(policyThreshold)) {
                        threshold = policyThreshold;
                    }

                    gs.info(
                        'POLICY: ' +
                        policyGR.getDisplayValue() +
                        ' | PASS THRESHOLD: ' +
                        threshold
                    );
                }
            } else {
                gs.info('NO POLICY FOUND ON ASSESSMENT - USING DEFAULT THRESHOLD 70');
            }

        } else {
            gs.info('ASSESSMENT NOT FOUND - USING DEFAULT THRESHOLD 70');
        }

        var gr = new GlideRecord('x_1858206_sentin_0_checklist_result');

        gr.addQuery('assessment', assessmentSysId.toString());

        gr.query();

        var total = 0;
        var passed = 0;
        var mandatoryFail = false;

        while (gr.next()) {

            total++;

            var result = gr.getValue('result');

            gs.info('FOUND RESULT: ' + result);

            if (result == 'pass') {
                passed++;
            }

            var mandatory = gr.getValue('mandatory');

            if (mandatory == 'true' && result != 'pass') {
                mandatoryFail = true;

                gs.info(
                    'MANDATORY FAILURE DETECTED: ' +
                    gr.getDisplayValue()
                );
            }
        }

        var score = (total === 0)
            ? 0
            : Math.round((passed / total) * 100);

        var gate = 'fail';

        if (!mandatoryFail && score >= threshold) {
            gate = 'pass';
        }

        gs.info(
            'SCORING SUMMARY | PASSED=' +
            passed +
            ' | TOTAL=' +
            total +
            ' | SCORE=' +
            score +
            ' | THRESHOLD=' +
            threshold +
            ' | MANDATORY_FAIL=' +
            mandatoryFail +
            ' | GATE=' +
            gate
        );

        return {
            score: score,
            passed: passed,
            total: total,
            gate: gate
        };
    },

    type: 'ReadinessScorer'
};
